public sealed class ChatIdentity{public string Id{get;set;}=Guid.NewGuid().ToString();public string PrivateKey{get;set;}="";public string PublicKey{get;set;}="";public string SignPrivate{get;set;}="";public string SignKey{get;set;}="";}
