internal static class PrivateChatCrypto
{
 internal static readonly JsonSerializerOptions Json=new(ServiceClient.Json){Encoder=System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping};
 internal static byte[] Pack(object value)=>JsonSerializer.SerializeToUtf8Bytes(value,Json);
 internal static byte[] Decode(string value)=>Convert.FromBase64String(value);
 internal static string B64(byte[] value)=>Convert.ToBase64String(value);
 internal static ChatIdentity Identity(){using var ec=ECDiffieHellman.Create(ECCurve.NamedCurves.nistP256);using var sign=ECDsa.Create(ECCurve.NamedCurves.nistP256);return new(){PrivateKey=B64(ec.ExportPkcs8PrivateKey()),PublicKey=B64(ec.ExportSubjectPublicKeyInfo()),SignPrivate=B64(sign.ExportPkcs8PrivateKey()),SignKey=B64(sign.ExportSubjectPublicKeyInfo())};}
 internal static string NewKey()=>B64(RandomNumberGenerator.GetBytes(32));
 private static object[] Extend(object[] values,params object[] extra)=>[..values,..extra];
 internal static ChatPacket Seal(string key,object[] context,object data,ChatIdentity identity){var nonce=RandomNumberGenerator.GetBytes(12);var plain=Pack(data);var cipher=new byte[plain.Length];var tag=new byte[16];using(var aes=new AesGcm(Decode(key),16))aes.Encrypt(nonce,plain,cipher,tag,Pack(Extend(context,identity.Id)));var packet=new ChatPacket{DeviceId=identity.Id,Nonce=B64(nonce),Body=B64([..cipher,..tag])};using var sign=ECDsa.Create();sign.ImportPkcs8PrivateKey(Decode(identity.SignPrivate),out _);packet.Signature=B64(sign.SignData(Pack(Extend(context,identity.Id,packet.Nonce,packet.Body)),HashAlgorithmName.SHA256,DSASignatureFormat.IeeeP1363FixedFieldConcatenation));return packet;}
 internal static T Open<T>(string key,object[] context,ChatPacket packet,ChatDevice signer){using var sign=ECDsa.Create();sign.ImportSubjectPublicKeyInfo(Decode(signer.SignKey),out _);if(signer.Id!=packet.DeviceId||!sign.VerifyData(Pack(Extend(context,packet.DeviceId,packet.Nonce,packet.Body)),Decode(packet.Signature),HashAlgorithmName.SHA256,DSASignatureFormat.IeeeP1363FixedFieldConcatenation))throw new CryptographicException("Message signature is invalid.");var body=Decode(packet.Body);if(body.Length<16)throw new CryptographicException();var plain=new byte[body.Length-16];using(var aes=new AesGcm(Decode(key),16))aes.Decrypt(Decode(packet.Nonce),body.AsSpan(0,plain.Length),body.AsSpan(plain.Length),plain,Pack(Extend(context,packet.DeviceId)));return JsonSerializer.Deserialize<T>(plain,Json)??throw new CryptographicException();}
 private static string Derive(string privateKey,string publicKey){using var ec=ECDiffieHellman.Create();ec.ImportPkcs8PrivateKey(Decode(privateKey),out _);using var other=ECDiffieHellman.Create();other.ImportSubjectPublicKeyInfo(Decode(publicKey),out _);var raw=ec.DeriveRawSecretAgreement(other.PublicKey);return B64(HKDF.DeriveKey(HashAlgorithmName.SHA256,raw,32,Encoding.UTF8.GetBytes("PetService-chat-v1"),Encoding.UTF8.GetBytes("room-key")));}
 internal static ChatEnvelope Wrap(string key,string room,int generation,ChatDevice recipient,ChatIdentity identity){var ephemeral=Identity();var packet=Seal(Derive(ephemeral.PrivateKey,recipient.PublicKey),["room-key",room,generation,recipient.Id,ephemeral.PublicKey],new{key},identity);return new(){RecipientId=recipient.Id,Ephemeral=ephemeral.PublicKey,DeviceId=packet.DeviceId,Nonce=packet.Nonce,Body=packet.Body,Signature=packet.Signature};}
 internal static string Unwrap(string room,int generation,ChatEnvelope envelope,ChatIdentity identity,ChatDevice signer)=>Open<Dictionary<string,string>>(Derive(identity.PrivateKey,envelope.Ephemeral),["room-key",room,generation,identity.Id,envelope.Ephemeral],envelope,signer)["key"];
 internal static string Fingerprint(ChatDevice device)=>string.Join(' ',Convert.ToHexStringLower(SHA256.HashData(Pack(new[]{device.PublicKey,device.SignKey}))).Chunk(8).Select(chars=>new string(chars)));
 internal static string Backup(ChatVault vault,string password){if(password.Length<8)throw new InvalidOperationException("Use at least eight characters for the backup password.");var salt=RandomNumberGenerator.GetBytes(16);var nonce=RandomNumberGenerator.GetBytes(12);var plain=Pack(vault);var body=new byte[plain.Length];var tag=new byte[16];var key=Rfc2898DeriveBytes.Pbkdf2(Encoding.UTF8.GetBytes(password),salt,600000,HashAlgorithmName.SHA256,32);using(var aes=new AesGcm(key,16))aes.Encrypt(nonce,plain,body,tag,Encoding.UTF8.GetBytes("PetService-chat-backup-v1"));return JsonSerializer.Serialize(new{format="PetService-chat-backup-v1",salt=B64(salt),nonce=B64(nonce),body=B64([..body,..tag])},Json);}
 internal static ChatVault Restore(string json,string password){var d=JsonSerializer.Deserialize<Dictionary<string,string>>(json,Json)!;if(d["format"]!="PetService-chat-backup-v1")throw new CryptographicException();var key=Rfc2898DeriveBytes.Pbkdf2(Encoding.UTF8.GetBytes(password),Decode(d["salt"]),600000,HashAlgorithmName.SHA256,32);var body=Decode(d["body"]);var plain=new byte[body.Length-16];using(var aes=new AesGcm(key,16))aes.Decrypt(Decode(d["nonce"]),body.AsSpan(0,plain.Length),body.AsSpan(plain.Length),plain,Encoding.UTF8.GetBytes(d["format"]));return JsonSerializer.Deserialize<ChatVault>(plain,Json)!;}
 // DPAPI protects local keys and drafts for the logged-in Windows user. There is no plaintext fallback.
 [StructLayout(LayoutKind.Sequential)]private struct Blob{public int Size;public IntPtr Data;}
 [DllImport("crypt32.dll",SetLastError=true,CharSet=CharSet.Unicode)]private static extern bool CryptProtectData(ref Blob input,string? description,IntPtr entropy,IntPtr reserved,IntPtr prompt,uint flags,out Blob output);
 [DllImport("crypt32.dll",SetLastError=true)]private static extern bool CryptUnprotectData(ref Blob input,IntPtr description,IntPtr entropy,IntPtr reserved,IntPtr prompt,uint flags,out Blob output);
 [DllImport("kernel32.dll")]private static extern IntPtr LocalFree(IntPtr memory);
 private static byte[] Protect(byte[] bytes,bool encrypt){var input=new Blob{Size=bytes.Length,Data=Marshal.AllocHGlobal(bytes.Length)};Blob output=default;try{Marshal.Copy(bytes,0,input.Data,bytes.Length);var ok=encrypt?CryptProtectData(ref input,null,IntPtr.Zero,IntPtr.Zero,IntPtr.Zero,1,out output):CryptUnprotectData(ref input,IntPtr.Zero,IntPtr.Zero,IntPtr.Zero,IntPtr.Zero,1,out output);if(!ok)throw new CryptographicException("Protected chat storage is unavailable.");var result=new byte[output.Size];Marshal.Copy(output.Data,result,0,result.Length);return result;}finally{Marshal.FreeHGlobal(input.Data);if(output.Data!=IntPtr.Zero)LocalFree(output.Data);}}
 internal static string Store(ChatVault value)=>B64(Protect(Pack(value),true));
 internal static ChatVault Load(string value)=>JsonSerializer.Deserialize<ChatVault>(Protect(Decode(value),false),Json)!;
}
